package com.yuyutian.mytools.media.library.service;
import com.yuyutian.mytools.media.library.model.MediaModels.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;
import java.time.Instant;import java.util.*;import static org.assertj.core.api.Assertions.*;
/** Media Library 领域事务测试。 */ @SpringBootTest class MediaLibraryServiceTest {
 @Autowired private MediaLibraryService service;
 @Test void shouldMergeEventCompleteAnalysisAndProtectProgressRevision(){UUID asset=UUID.randomUUID();AssetEvent event=new AssetEvent("event-1",asset,7L,"MEDIA_FILE","42","video.mp4","video/mp4",100,"a".repeat(64),"movies","Movies");MediaView media=service.consume(event);assertThat(service.consume(event).id()).isEqualTo(media.id());UUID task=UUID.randomUUID();service.begin(media.id(),new BeginAnalysis("analysis-v1",task));CompleteAnalysis completed=new CompleteAnalysis(task,"summary","description",List.of(new TagInput("Travel",0.9)),List.of(new ArtifactInput(UUID.randomUUID(),"THUMBNAIL","1.0.0")));service.complete(media.id(),completed);service.complete(media.id(),completed);assertThatThrownBy(()->service.complete(media.id(),new CompleteAnalysis(task,"different","description",List.of(),List.of()))).isInstanceOf(IllegalStateException.class);assertThat(service.view(7,media.id()).tags()).containsExactly("travel");ProgressView first=service.progress(7,media.id(),new ProgressRequest(100,1000,false,0,Instant.now()));assertThat(first.revision()).isEqualTo(1);assertThatThrownBy(()->service.progress(7,media.id(),new ProgressRequest(200,1000,false,0,Instant.now()))).isInstanceOf(IllegalStateException.class);}
 @Test void shouldRejectEventIdWithDifferentPayload(){service.consume(new AssetEvent("event-conflict",UUID.randomUUID(),9L,"MEDIA_FILE","1","a.jpg","image/jpeg",5,"b".repeat(64),null,null));assertThatThrownBy(()->service.consume(new AssetEvent("event-conflict",UUID.randomUUID(),9L,"MEDIA_FILE","2","b.jpg","image/jpeg",6,"c".repeat(64),null,null))).isInstanceOf(IllegalStateException.class);}
}
